package br.gov.caixa.loterias.feature.onboarding

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.foundation.Image
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.asImageBitmap
import androidx.compose.ui.layout.ContentScale

/** Selo de jogo responsável original da tela de restrição etária. */
@Composable
internal fun LegacyResponsibleGamingIcon(modifier: Modifier = Modifier) {
    val bitmap = remember {
        val bytes = Base64.decode(LEGACY_RESPONSIBLE_GAMING_ICON, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size).asImageBitmap()
    }
    Image(
        bitmap = bitmap,
        contentDescription = "Apostar é para maiores de 18 anos",
        modifier = modifier,
        contentScale = ContentScale.Fit,
    )
}

private const val LEGACY_RESPONSIBLE_GAMING_ICON = ""
